using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityNeonWallArtVerify{class Site{public string owner,art;public Vector3 p,n,camera;public float w,h;}static CityNeonWallArtVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityNeonWallArtVerify.request"))return;File.Delete("CityNeonWallArtVerify.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="City Road Facing Neon Wall Art");var sites=File.ReadAllLines("FinalEnvironmentRoadReview/CityNeonWallArtPlacements.csv").Skip(1).Select(line=>{var a=line.Split(',');return new Site{owner=a[0],p=new Vector3(float.Parse(a[1]),float.Parse(a[2]),float.Parse(a[3])),n=new Vector3(float.Parse(a[4]),0,float.Parse(a[5])),w=float.Parse(a[6]),h=float.Parse(a[7]),art=a[8],camera=new Vector3(float.Parse(a[9]),float.Parse(a[10]),float.Parse(a[11]))};}).ToArray();foreach(var lod in root.GetComponentsInChildren<LODGroup>()){var r=lod.GetComponent<Renderer>();lod.SetLODs(new[]{new LOD(.025f,new[]{r})});lod.RecalculateBounds();lod.size=Mathf.Clamp(lod.size,5,14);}PrefabUtility.SaveAsPrefabAsset(root,"Assets/Scenes/Oasis/CityNeonWallArt/City Road Facing Neon Wall Art.prefab");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var chosen=new List<Site>();foreach(var target in new[]{new Vector3(-440,32,-400),new Vector3(-110,32,-230),new Vector3(200,32,240),new Vector3(550,32,350)}){var s=sites.Where(s=>!chosen.Contains(s)&&s.h>2).OrderBy(s=>Vector3.Distance(s.p,target)).First();chosen.Add(s);}chosen.Add(sites.Where(s=>s.h<1.9f).OrderByDescending(s=>s.w).First());chosen.Add(sites.Where(s=>s.art=="PLAY NEXT").OrderByDescending(s=>s.h).First());var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);try{ctrl.ApplyDay();for(int i=0;i<chosen.Count;i++){var s=chosen[i];var direction=(s.camera-s.p).normalized;float distance=Mathf.Min(Vector3.Distance(s.camera,s.p),Mathf.Max(9,s.w*2.1f));var camera=s.p+direction*distance;capture.Invoke(null,new object[]{scene,camera,s.p,"City-Neon-Wall-Art-Day-"+(i+1)});}ctrl.ApplyNight();for(int i=0;i<2;i++){var s=chosen[i];var direction=(s.camera-s.p).normalized;float distance=Mathf.Min(Vector3.Distance(s.camera,s.p),Mathf.Max(9,s.w*2.1f));capture.Invoke(null,new object[]{scene,s.p+direction*distance,s.p,"City-Neon-Wall-Art-Night-"+(i+1)});}}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}var filters=root.GetComponentsInChildren<MeshFilter>(true);var materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().ToArray();bool flipped=filters.All(f=>{var uv=f.sharedMesh.uv;for(int i=0;i<uv.Length;i+=4)if(uv[i].x<uv[i+1].x)return false;return true;});File.WriteAllText("FinalEnvironmentRoadReview/CityNeonWallArtVerified.txt","SUCCESS 6 daytime district/low-wall/controller views and 2 night views captured. Road facing cutout art="+sites.Length+" combined meshes="+filters.Length+" total triangles="+filters.Sum(f=>f.sharedMesh.triangles.Length/3)+"; existing shared materials="+materials.Length+" new lights="+root.GetComponentsInChildren<Light>(true).Length+" new colliders="+root.GetComponentsInChildren<Collider>(true).Length+" UV text orientation correct="+flipped+" cutout marker preserved="+filters.All(f=>f.sharedMesh.colors.All(c=>c.a<-.5f))+" shader errors="+materials.Any(m=>ShaderUtil.ShaderHasError(m.shader))+". Bounded distance culling saved.\n"+string.Join("\n",chosen.Select(s=>s.owner+" "+s.art+" at "+s.p)));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CityNeonWallArtVerified.txt",e.ToString());Debug.LogException(e);}}}
